function debounce(fn, wait) {
  let timer;
  function wrapped(...args) {
    const ctx = this;
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(ctx, args), wait);
  }
  wrapped.cancel = () => clearTimeout(timer);
  return wrapped;
}
