import os

def env_config(prefix, defaults=None, environ=None):
    environ = environ if environ is not None else os.environ
    cfg = {}
    def assign(path, value):
        node = cfg
        for part in path[:-1]:
            node = node.setdefault(part, {})
        node[path[-1]] = value
    p = prefix.upper().rstrip('_') + '_'
    for key, value in environ.items():
        if key.startswith(p):
            assign(key[len(p):].lower().split('_'), value)
    def merge(a, b):
        out = dict(a)
        for k, v in b.items():
            if isinstance(v, dict) and isinstance(out.get(k), dict):
                out[k] = merge(out[k], v)
            else:
                out[k] = v
        return out
    return merge(defaults or {}, cfg)

