function intersection(a, b) {
  const setB = new Set(b);
  const out = [];
  const seen = new Set();
  for (const item of a) {
    if (setB.has(item) && !seen.has(item)) {
      seen.add(item);
      out.push(item);
    }
  }
  return out;
}

