class EventEmitter {
  constructor() {
    this.events = new Map();
  }
  on(name, fn) {
    const list = this.events.get(name) || [];
    list.push(fn);
    this.events.set(name, list);
    return () => this.off(name, fn);
  }
  off(name, fn) {
    const list = (this.events.get(name) || []).filter((f) => f !== fn);
    this.events.set(name, list);
  }
  once(name, fn) {
    const wrap = (...args) => {
      this.off(name, wrap);
      fn(...args);
    };
    return this.on(name, wrap);
  }
  emit(name, ...args) {
    for (const fn of [...(this.events.get(name) || [])]) fn(...args);
  }
}
