class Node:
    def __init__(self, val, left=None, right=None):
        self.val, self.left, self.right = val, left, right

def serialize(root):
    out = []
    def walk(n):
        if n is None:
            out.append(None)
            return
        out.append(n.val)
        walk(n.left)
        walk(n.right)
    walk(root)
    return out

def deserialize(data):
    it = iter(data)
    def build():
        val = next(it)
        if val is None:
            return None
        return Node(val, build(), build())
    return build()

root = Node(1, Node(2), Node(3, None, Node(4)))
assert serialize(deserialize(serialize(root))) == serialize(root)
```

None markers make the encoding unambiguous. A queue-based level order works too if you prefer BFS.

